               ++it;
               skip_expected_whitespace();
               break;
            }
            case Number: {
               const auto value = read_json_number<Opts.null_terminated>(it, end);
               dump<false>(value, b, ix); // we couldn't have gotten here without one valid character
               skip_whitespace();
               break;
            }
            case Colon: {
               dump<':', false>(b, ix);
               ++it;
               skip_whitespace();
               break;
            }
            case Array_Start: {
               dump<'[', false>(b, ix);
               ++it;
               skip_expected_whitespace();
               break;
            }
            case Array_End: {
               dump<']', false>(b, ix);
               ++it;
               skip_whitespace();
               break;
            }
            case Null: {
               dump<"null", false>(b, ix);
               it += 4;
               skip_whitespace();
               break;
            }
            case Bool: {
